async function complete(job: ClaimedJob<ReceiptJob>): Promise<void> {
  const stored = await storeReceipt(job.payload);
  try {
    await transaction(async (client) => {
      await advisoryLock(client, job.payload.customerId);
      const allowed = await client.query(
        `SELECT 1 FROM customers.customers c
         WHERE c.merchant_id=$1 AND c.id=$2 AND c.status='active'
           AND NOT EXISTS (SELECT 1 FROM operations.erasure_requests e
                           WHERE e.merchant_id=$1 AND e.customer_id=$2)`,
        [job.merchant_id, job.payload.customerId],
      );
      if (!allowed.rowCount) throw new Error('customer_erasure_in_progress');
      await recordReceiptManifest(client, {
        merchantId: job.merchant_id,
        customerId: job.payload.customerId,
        paymentId: job.payload.paymentId,
        objectKey: stored.objectKey,
        checksum: stored.checksum,
      });
      await addReceiptEvent(client, job, stored.objectKey);
      await completeJob(client, job);
    });
  } catch (error) {
    try { await objectStore.removeObject(DOCUMENT_BUCKET, stored.objectKey); } catch { /* cleanup retries with erasure */ }
    throw error;
  }
}

